      background-position: right 8px center;
    }

    .btn-signin {
      background: var(--red);
      color: var(--white);
      border: none;
      padding: 8px 20px;
      border-radius: 4px;
      font-size: 0.9rem;
      font-weight: 600;
      transition: background 0.2s;
    }
    .btn-signin:hover { background: var(--red-dark); }

    /* ─── HERO ─── */
    .hero {
      position: relative;
      min-height: 100vh;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      text-align: center;
      padding: 120px 24px 80px;
      overflow: hidden;
    }

    .hero-mosaic {
      position: absolute;
      inset: 0;
      display: grid;
      grid-template-columns: repeat(7, 1fr);
      grid-template-rows: repeat(4, 1fr);
      gap: 4px;
      transform: rotate(-3deg) scale(1.15);
      pointer-events: none;
